/* ============================================
   StayQuest — Design System & Styles
   ============================================ */

/* Google Fonts */
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,300;0,400;0,500;0,600;0,700;0,800&family=Space+Grotesk:wght@400;500;600;700&display=swap');

/* ---------- CSS Custom Properties ---------- */
:root {
  /* Brand Colors */
  --navy: #003B95;
  --navy-dark: #002868;
  --navy-light: #0050C8;
  --blue: #006CE4;
  --blue-light: #3D9BFF;
  --gold: #FFB700;
  --gold-light: #FFC933;
  --gold-dark: #E5A500;

  /* Surfaces */
  --bg-primary: #FFFFFF;
  --bg-secondary: #F5F6F8;
  --bg-tertiary: #EBEDF0;
  --bg-navy: #003B95;

  /* Text */
  --text-primary: #1A1A2E;
  --text-secondary: #4A4A68;
  --text-muted: #6B6B8D;
  --text-inverse: #FFFFFF;
  --text-navy: #003B95;

  /* Borders */
  --border-light: #E0E0E8;
  --border-medium: #C8C8D4;
  --border-navy: #0050C8;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0,59,149,0.08);
  --shadow-md: 0 4px 12px rgba(0,59,149,0.1);
  --shadow-lg: 0 8px 30px rgba(0,59,149,0.12);
  --shadow-xl: 0 16px 48px rgba(0,59,149,0.15);

  /* Typography */
  --font-heading: 'Space Grotesk', sans-serif;
  --font-body: 'Plus Jakarta Sans', sans-serif;

  /* Spacing */
  --section-padding: 80px;
  --container-width: 1200px;

  /* Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-normal: 250ms ease;
  --transition-slow: 400ms ease;
}

/* ---------- Reset & Base ---------- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--bg-primary);
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; }
ul { list-style: none; }

/* ---------- Typography ---------- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--text-primary);
}

.heading-xl { font-size: clamp(32px, 5vw, 52px); letter-spacing: -1px; }
.heading-lg { font-size: clamp(24px, 3.5vw, 36px); letter-spacing: -0.5px; }
.heading-md { font-size: clamp(20px, 2.5vw, 28px); }
.heading-sm { font-size: 18px; }

.text-secondary { color: var(--text-secondary); }
.text-muted { color: var(--text-muted); }
.text-navy { color: var(--navy); }
.text-blue { color: var(--blue); }
.text-gold { color: var(--gold-dark); }
.text-white { color: #fff; }

/* ---------- Layout ---------- */
.container {
  max-width: var(--container-width);
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: var(--section-padding) 0;
}

.section-header {
  margin-bottom: 40px;
}

.section-header .subtitle {
  color: var(--text-secondary);
  font-size: 16px;
  margin-top: 8px;
}

/* ---------- Navigation ---------- */
.site-header {
  background: var(--navy);
  position: sticky;
  top: 0;
  z-index: 1000;
}

.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 24px;
  max-width: var(--container-width);
  margin: 0 auto;
}

.logo {
  font-family: var(--font-heading);
  font-size: 22px;
  font-weight: 700;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 6px;
}

.logo-icon {
  width: 32px;
  height: 32px;
  background: var(--gold);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  font-weight: 800;
  color: var(--navy-dark);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.header-nav-tabs {
  display: flex;
  gap: 0;
  background: rgba(0,0,0,0.15);
  border-radius: var(--radius-sm);
  padding: 3px;
}

.nav-tab {
  padding: 8px 16px;
  color: rgba(255,255,255,0.75);
  font-size: 13px;
  font-weight: 500;
  border-radius: 4px;
  transition: var(--transition-fast);
  white-space: nowrap;
}

.nav-tab:hover {
  color: #fff;
  background: rgba(255,255,255,0.1);
}

.nav-tab.active {
  color: #fff;
  background: rgba(255,255,255,0.2);
}

.header-btn {
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 600;
  border-radius: var(--radius-sm);
  border: none;
  transition: var(--transition-fast);
}

.btn-outline-light {
  background: transparent;
  color: #fff;
  border: 1px solid rgba(255,255,255,0.3);
}

.btn-outline-light:hover {
  background: rgba(255,255,255,0.1);
}

.btn-register {
  background: var(--gold);
  color: var(--navy-dark);
}

.btn-register:hover {
  background: var(--gold-light);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: #fff;
  padding: 8px;
}

/* ---------- Hero Sections ---------- */
.hero {
  background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy) 40%, var(--blue) 100%);
  padding: 60px 0 80px;
  position: relative;
  overflow: hidden;
}

.hero::after {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 60%;
  height: 200%;
  background: radial-gradient(ellipse, rgba(255,183,0,0.08) 0%, transparent 70%);
  pointer-events: none;
}

.hero .container {
  position: relative;
  z-index: 1;
}

.hero-title {
  font-family: var(--font-heading);
  font-size: clamp(32px, 5vw, 48px);
  font-weight: 700;
  color: #fff;
  margin-bottom: 8px;
  letter-spacing: -0.5px;
}

.hero-subtitle {
  color: rgba(255,255,255,0.8);
  font-size: 18px;
  margin-bottom: 32px;
}

/* ---------- Search Forms ---------- */
.search-form {
  background: var(--bg-yellow-accent, #FEBA02);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-xl);
}

.search-form.stays-form {
  background: #FEBA02;
}

.search-form.packages-form {
  background: #FEBA02;
}

.search-form.car-form {
  background: #FEBA02;
}

.search-form.attractions-form {
  background: #FEBA02;
}

.search-row {
  display: flex;
  gap: 8px;
  align-items: flex-end;
}

.search-field {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.search-field label {
  font-size: 11px;
  font-weight: 700;
  color: var(--navy-dark);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.search-field input,
.search-field select {
  padding: 12px 14px;
  border: 2px solid transparent;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-family: var(--font-body);
  background: #fff;
  color: var(--text-primary);
  transition: var(--transition-fast);
  width: 100%;
}

.search-field input:focus,
.search-field select:focus {
  outline: none;
  border-color: var(--navy);
}

.search-field input::placeholder {
  color: var(--text-muted);
}

.search-btn {
  padding: 12px 32px;
  background: var(--navy);
  color: #fff;
  border: none;
  border-radius: var(--radius-sm);
  font-size: 16px;
  font-weight: 700;
  transition: var(--transition-fast);
  white-space: nowrap;
  height: 46px;
}

.search-btn:hover {
  background: var(--navy-dark);
}

.search-extras {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 12px;
}

.search-extras label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: var(--navy-dark);
  cursor: pointer;
  font-weight: 500;
}

.search-extras input[type="checkbox"] {
  accent-color: var(--navy);
  width: 16px;
  height: 16px;
}

.radio-group {
  display: flex;
  gap: 16px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.radio-group label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: var(--navy-dark);
  cursor: pointer;
  font-weight: 600;
}

.radio-group input[type="radio"] {
  accent-color: var(--navy);
  width: 16px;
  height: 16px;
}

/* ---------- Trust Badges ---------- */
.trust-badges {
  background: var(--bg-secondary);
  padding: 32px 0;
  border-bottom: 1px solid var(--border-light);
}

.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.trust-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
}

.trust-icon {
  width: 40px;
  height: 40px;
  background: var(--navy);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.trust-icon svg {
  width: 20px;
  height: 20px;
  stroke: #fff;
  fill: none;
  stroke-width: 2;
}

.trust-item h4 {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 2px;
  color: var(--text-primary);
}

.trust-item p {
  font-size: 12px;
  color: var(--text-muted);
  line-height: 1.4;
}

/* ---------- Offers ---------- */
.offers-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.offer-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  min-height: 240px;
  display: flex;
  align-items: flex-end;
  transition: var(--transition-normal);
}

.offer-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.offer-card.getaway {
  background: linear-gradient(135deg, #0D4F8B 0%, #1B6FB5 60%, #3D9BFF 100%);
}

.offer-card.credit-card {
  background: linear-gradient(135deg, #1A1A2E 0%, #2D2D4A 60%, #4A4A68 100%);
}

.offer-content {
  padding: 32px;
  color: #fff;
  width: 100%;
}

.offer-content h3 {
  font-size: 24px;
  color: #fff;
  margin-bottom: 8px;
}

.offer-content p {
  font-size: 14px;
  color: rgba(255,255,255,0.8);
  margin-bottom: 16px;
  max-width: 400px;
}

.offer-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 20px;
  background: #fff;
  color: var(--navy);
  border: none;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 700;
  transition: var(--transition-fast);
}

.offer-btn:hover {
  background: var(--gold);
  color: var(--navy-dark);
}

/* ---------- Property Types ---------- */
.property-types-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.property-type-chip {
  padding: 8px 18px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: 100px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  transition: var(--transition-fast);
  cursor: pointer;
}

.property-type-chip:hover {
  background: var(--navy);
  color: #fff;
  border-color: var(--navy);
}

/* ---------- Tabs ---------- */
.tab-bar {
  display: flex;
  gap: 4px;
  border-bottom: 2px solid var(--border-light);
  margin-bottom: 24px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding-bottom: 0;
}

.tab-bar::-webkit-scrollbar { display: none; }

.tab-btn {
  padding: 10px 18px;
  background: none;
  border: none;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-muted);
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  white-space: nowrap;
  transition: var(--transition-fast);
}

.tab-btn:hover {
  color: var(--navy);
}

.tab-btn.active {
  color: var(--navy);
  border-bottom-color: var(--navy);
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

/* ---------- Trip Planner ---------- */
.trip-planner-destinations {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 16px;
}

.destination-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--border-light);
  transition: var(--transition-normal);
  cursor: pointer;
}

.destination-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.destination-card-img {
  height: 120px;
  background: linear-gradient(135deg, #E8D5B7 0%, #C9A96E 100%);
  position: relative;
}

.destination-card-img::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.3), transparent);
}

.destination-card-body {
  padding: 12px;
}

.destination-card-body h4 {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 2px;
}

.destination-card-body p {
  font-size: 12px;
  color: var(--text-muted);
}

/* ---------- Property Cards ---------- */
.property-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--border-light);
  background: #fff;
  transition: var(--transition-normal);
}

.property-card:hover {
  box-shadow: var(--shadow-md);
}

.property-card-img {
  height: 180px;
  position: relative;
  overflow: hidden;
}

.property-card-img .img-placeholder {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.property-card-body {
  padding: 16px;
}

.property-card-name {
  font-size: 15px;
  font-weight: 700;
  margin-bottom: 4px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.property-card-location {
  font-size: 13px;
  color: var(--text-muted);
  margin-bottom: 8px;
}

.property-card-rating {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.rating-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--navy);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: var(--radius-sm) var(--radius-sm) var(--radius-sm) 0;
  min-width: 36px;
}

.rating-text {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.rating-count {
  font-size: 12px;
  color: var(--text-muted);
}

.property-card-price {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.price-original {
  font-size: 13px;
  color: var(--text-muted);
  text-decoration: line-through;
}

.price-current {
  font-size: 18px;
  font-weight: 800;
  color: var(--text-primary);
}

.price-night {
  font-size: 12px;
  color: var(--text-muted);
}

.price-sale {
  color: #B91C1C;
}

/* ---------- Carousel ---------- */
.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 4px 0;
}

.carousel-track::-webkit-scrollbar { display: none; }

.carousel-track .property-card {
  min-width: 280px;
  flex-shrink: 0;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-70%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: #fff;
  border: 1px solid var(--border-light);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: var(--transition-fast);
}

.carousel-btn:hover {
  background: var(--navy);
  color: #fff;
  border-color: var(--navy);
}

.carousel-btn svg {
  width: 20px;
  height: 20px;
}

.carousel-btn.prev { left: -22px; }
.carousel-btn.next { right: -22px; }

/* ---------- Trending Destinations ---------- */
.trending-list {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.trending-chip {
  padding: 10px 24px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  transition: var(--transition-fast);
  cursor: pointer;
}

.trending-chip:hover {
  background: var(--navy);
  color: #fff;
  border-color: var(--navy);
}

/* ---------- Explore Destinations Grid ---------- */
.explore-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 16px;
}

.explore-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  transition: var(--transition-fast);
  cursor: pointer;
}

.explore-card:hover {
  border-color: var(--navy);
  box-shadow: var(--shadow-sm);
}

.explore-card-img {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  flex-shrink: 0;
}

.explore-card-img .img-placeholder {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.explore-card-info h4 {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 2px;
}

.explore-card-info p {
  font-size: 12px;
  color: var(--text-muted);
}

/* ---------- Weekend Deals ---------- */
.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 20px;
}

.deal-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--border-light);
  background: #fff;
  transition: var(--transition-normal);
}

.deal-card:hover {
  box-shadow: var(--shadow-md);
}

.deal-card-img {
  height: 160px;
  position: relative;
  overflow: hidden;
}

.deal-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background: #B91C1C;
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 4px;
  z-index: 1;
}

.deal-card-body {
  padding: 16px;
}

.deal-card-name {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 2px;
}

.deal-card-location {
  font-size: 12px;
  color: var(--text-muted);
  margin-bottom: 8px;
}

.deal-card-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
}

.deal-card-duration {
  font-size: 12px;
  color: var(--text-secondary);
  margin-bottom: 6px;
}

.deal-card-prices {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

/* ---------- Homes Guests Love ---------- */
.homes-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 20px;
}

/* ---------- Loyalty CTA ---------- */
.loyalty-cta {
  background: linear-gradient(135deg, var(--navy) 0%, var(--blue) 100%);
  padding: 60px 0;
  text-align: center;
  color: #fff;
}

.loyalty-cta h2 {
  color: #fff;
  font-size: clamp(24px, 3vw, 36px);
  margin-bottom: 8px;
}

.loyalty-cta .sub {
  font-size: 18px;
  color: rgba(255,255,255,0.9);
  margin-bottom: 8px;
  font-weight: 600;
}

.loyalty-cta p {
  color: rgba(255,255,255,0.75);
  font-size: 15px;
  margin-bottom: 24px;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

.loyalty-btns {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.btn-primary {
  padding: 12px 28px;
  background: var(--gold);
  color: var(--navy-dark);
  border: none;
  border-radius: var(--radius-sm);
  font-size: 15px;
  font-weight: 700;
  transition: var(--transition-fast);
}

.btn-primary:hover {
  background: var(--gold-light);
}

.btn-secondary-outline {
  padding: 12px 28px;
  background: transparent;
  color: #fff;
  border: 2px solid rgba(255,255,255,0.4);
  border-radius: var(--radius-sm);
  font-size: 15px;
  font-weight: 700;
  transition: var(--transition-fast);
}

.btn-secondary-outline:hover {
  border-color: #fff;
  background: rgba(255,255,255,0.1);
}

/* ---------- Popular Links ---------- */
.popular-links-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 8px;
}

.popular-link {
  padding: 8px 12px;
  font-size: 13px;
  color: var(--navy);
  font-weight: 500;
  border-radius: var(--radius-sm);
  transition: var(--transition-fast);
  cursor: pointer;
}

.popular-link:hover {
  background: var(--bg-secondary);
  color: var(--navy-dark);
}

/* ---------- Accordion / FAQ ---------- */
.accordion {
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.accordion-item {
  border-bottom: 1px solid var(--border-light);
}

.accordion-item:last-child {
  border-bottom: none;
}

.accordion-trigger {
  width: 100%;
  padding: 18px 20px;
  background: #fff;
  border: none;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  text-align: left;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  transition: var(--transition-fast);
}

.accordion-trigger:hover {
  background: var(--bg-secondary);
}

.accordion-trigger svg {
  width: 18px;
  height: 18px;
  transition: transform var(--transition-normal);
  flex-shrink: 0;
  color: var(--text-muted);
}

.accordion-item.open .accordion-trigger svg {
  transform: rotate(180deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-normal);
}

.accordion-content-inner {
  padding: 0 20px 18px;
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.7;
}

/* ---------- Rental Companies ---------- */
.companies-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  justify-content: center;
}

.company-logo {
  width: 120px;
  height: 60px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  font-weight: 700;
  color: var(--text-secondary);
  transition: var(--transition-fast);
}

.company-logo:hover {
  border-color: var(--navy);
  box-shadow: var(--shadow-sm);
}

/* ---------- Credit Card Promo ---------- */
.credit-promo {
  background: linear-gradient(135deg, #1A1A2E 0%, #2D2D4A 100%);
  border-radius: var(--radius-lg);
  padding: 40px;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.credit-promo h3 {
  color: #fff;
  font-size: 22px;
  margin-bottom: 8px;
}

.credit-promo p {
  color: rgba(255,255,255,0.75);
  font-size: 14px;
  margin-bottom: 16px;
}

/* ---------- Recommended Activities ---------- */
.activity-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.activity-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  transition: var(--transition-fast);
  cursor: pointer;
}

.activity-item:hover {
  border-color: var(--navy);
  box-shadow: var(--shadow-sm);
}

.activity-icon {
  width: 56px;
  height: 56px;
  background: var(--bg-secondary);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.activity-icon svg {
  width: 24px;
  height: 24px;
  stroke: var(--navy);
  fill: none;
  stroke-width: 2;
}

.activity-info h4 {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 2px;
}

.activity-info p {
  font-size: 12px;
  color: var(--text-muted);
}

/* ---------- Footer ---------- */
.site-footer {
  background: var(--navy-dark);
  color: rgba(255,255,255,0.8);
  padding: 60px 0 24px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 40px;
}

.footer-col h4 {
  font-size: 13px;
  font-weight: 700;
  color: #fff;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.footer-col a {
  display: block;
  font-size: 13px;
  color: rgba(255,255,255,0.65);
  padding: 4px 0;
  transition: var(--transition-fast);
}

.footer-col a:hover {
  color: #fff;
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  text-align: center;
}

.footer-bottom p {
  font-size: 12px;
  color: rgba(255,255,255,0.45);
  max-width: 800px;
  margin: 0 auto;
  line-height: 1.6;
}

/* ---------- Image Placeholders ---------- */
.img-placeholder {
  display: block;
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
}

.img-placeholder.beach { background: linear-gradient(135deg, #87CEEB 0%, #4682B4 50%, #1E90FF 100%); }
.img-placeholder.city { background: linear-gradient(135deg, #4A5568 0%, #2D3748 50%, #1A202C 100%); }
.img-placeholder.mountain { background: linear-gradient(135deg, #7FB069 0%, #4A7C59 50%, #2D5016 100%); }
.img-placeholder.desert { background: linear-gradient(135deg, #E8D5B7 0%, #C9A96E 50%, #A67C3D 100%); }
.img-placeholder.tropical { background: linear-gradient(135deg, #00CED1 0%, #20B2AA 50%, #008B8B 100%); }
.img-placeholder.hotel { background: linear-gradient(135deg, #B0C4DE 0%, #778899 50%, #5F7A8A 100%); }
.img-placeholder.resort { background: linear-gradient(135deg, #FF8C69 0%, #FF6347 50%, #CD5C5C 100%); }
.img-placeholder.castle { background: linear-gradient(135deg, #9B8EC1 0%, #7B68AE 50%, #5B4A8A 100%); }
.img-placeholder.lodge { background: linear-gradient(135deg, #8B7355 0%, #6B5735 50%, #4A3B1F 100%); }
.img-placeholder.urban { background: linear-gradient(135deg, #6C7A89 0%, #4B5562 50%, #2F363D 100%); }
.img-placeholder.european { background: linear-gradient(135deg, #C4A77D 0%, #9B8465 50%, #7A6A52 100%); }
.img-placeholder.nature { background: linear-gradient(135deg, #6DAE58 0%, #4A8C3F 50%, #2E6B28 100%); }

/* ---------- Animations ---------- */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.fade-in {
  opacity: 0;
  transform: translateY(16px);
  transition: opacity 0.5s ease, transform 0.5s ease;
}

.fade-in.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ---------- Car Rental Destination Cards ---------- */
.rental-dest-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 16px;
}

.rental-dest-card {
  padding: 20px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  transition: var(--transition-fast);
  cursor: pointer;
}

.rental-dest-card:hover {
  border-color: var(--navy);
  box-shadow: var(--shadow-sm);
}

.rental-dest-card h4 {
  font-size: 15px;
  font-weight: 700;
  margin-bottom: 6px;
}

.rental-dest-card .locations {
  font-size: 12px;
  color: var(--text-muted);
  margin-bottom: 8px;
}

.rental-dest-card .price {
  font-size: 18px;
  font-weight: 800;
  color: var(--navy);
}

.rental-dest-card .price-label {
  font-size: 12px;
  color: var(--text-muted);
  font-weight: 400;
}

/* ---------- Attractions Explore Grid ---------- */
.attractions-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 12px;
}

.attraction-city-card {
  padding: 16px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  text-align: center;
  transition: var(--transition-fast);
  cursor: pointer;
}

.attraction-city-card:hover {
  border-color: var(--navy);
  box-shadow: var(--shadow-sm);
}

.attraction-city-card h4 {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 4px;
}

.attraction-city-card p {
  font-size: 12px;
  color: var(--text-muted);
}

/* ---------- Things to Do Links ---------- */
.things-links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.thing-link {
  padding: 6px 14px;
  background: var(--bg-secondary);
  border-radius: 100px;
  font-size: 13px;
  color: var(--navy);
  font-weight: 500;
  transition: var(--transition-fast);
  cursor: pointer;
}

.thing-link:hover {
  background: var(--navy);
  color: #fff;
}

/* ---------- Account CTA ---------- */
.account-cta {
  background: var(--bg-secondary);
  padding: 48px 0;
  text-align: center;
}

/* ---------- Nearby Destinations Grid ---------- */
.nearby-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 16px;
}

.nearby-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  cursor: pointer;
  transition: var(--transition-normal);
  border: 1px solid var(--border-light);
}

.nearby-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.nearby-card-img {
  height: 120px;
}

.nearby-card-body {
  padding: 12px;
}

.nearby-card-body h4 {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 2px;
}

.nearby-card-body p {
  font-size: 12px;
  color: var(--text-muted);
}

/* ---------- Section Title with CTA ---------- */
.section-header-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 24px;
}

.section-cta {
  font-size: 14px;
  font-weight: 600;
  color: var(--navy);
  transition: var(--transition-fast);
}

.section-cta:hover {
  color: var(--blue);
}

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  :root {
    --section-padding: 60px;
  }

  .trust-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .offers-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .credit-promo {
    flex-direction: column;
    text-align: center;
  }
}

@media (max-width: 768px) {
  :root {
