  .homes-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 24px;
  }

  .attractions-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rental-dest-grid {
    grid-template-columns: 1fr;
  }

  .nearby-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .radio-group {
    flex-direction: column;
    gap: 8px;
  }
